import{_ as t,o,c as i,ae as r}from"./chunks/framework.Czhw_PXq.js";const g=JSON.parse('{"title":"ADR 016: Cloud Architecture Pivot: Render, Turso, and Gemini","description":"","frontmatter":{},"headers":[],"relativePath":"adr/016-cloud-pivot-render-turso.md","filePath":"adr/016-cloud-pivot-render-turso.md"}'),n={name:"adr/016-cloud-pivot-render-turso.md"};function a(s,e,l,c,d,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-016-cloud-architecture-pivot-render-turso-and-gemini" tabindex="-1">ADR 016: Cloud Architecture Pivot: Render, Turso, and Gemini <a class="header-anchor" href="#adr-016-cloud-architecture-pivot-render-turso-and-gemini" aria-label="Permalink to &quot;ADR 016: Cloud Architecture Pivot: Render, Turso, and Gemini&quot;">​</a></h1><p>Date: 2026-03-04</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The initial deployment strategy relied on Hugging Face Spaces (Docker) running a monolithic container with:</p><ol><li>Node.js Backend</li><li>Ollama (Local LLM Inference) with Mistral</li><li>SQLite (Local File Persistence)</li></ol><p>However, we encountered significant blockers:</p><ol><li><strong>Timeout Issues</strong>: The &quot;heavy&quot; container (Ollama + Models) took &gt;5 minutes to start, causing Hugging Face health checks to fail consistently (&quot;Launch timed out&quot;).</li><li><strong>Resource Constraints</strong>: The free tier of Hugging Face Spaces (2 vCPU, 16GB RAM) struggled with simultaneous Node.js + Ollama inference load.</li><li><strong>Persistence Issues</strong>: SQLite on Docker containers in serverless-like environments is ephemeral. While we mounted a dataset, permissions and &quot;baked-in&quot; dependencies caused frequent <code>exit code 127</code> and write errors.</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We have decided to pivot to a <strong>Modular Cloud Architecture</strong> compatible with free-tier constraints:</p><ol><li><p><strong>Hosting: Render.com</strong></p><ul><li><strong>Why</strong>: Native Node.js support, faster build times, and zero-downtime deployments for web services.</li><li><strong>Tier</strong>: Free Tier (spins down after inactivity, but sufficient for TFM demo).</li></ul></li><li><p><strong>Database: Turso (LibSQL)</strong></p><ul><li><strong>Why</strong>: Serverless SQLite that solves the persistence problem. It offers a generous free tier (9GB storage, 1B requests).</li><li><strong>Change</strong>: Migrated from <code>better-sqlite3</code> to <code>@libsql/client</code>.</li></ul></li><li><p><strong>AI Inference: Google Gemini 2.5 Flash</strong></p><ul><li><strong>Why</strong>: To remove the heavy Ollama dependency from the application container.</li><li><strong>Performance</strong>: Gemini 2.5 Flash is extremely fast and provides a free tier via Google AI Studio, decoupling inference load from our hosting server.</li><li><strong>Integration</strong>: Using <code>Google Genkit</code> for structured output and type safety.</li></ul></li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li><strong>Deployment Stability</strong>: Application startup is now instant (&lt;5s) as it no longer loads AI models into memory.</li><li><strong>Persistence</strong>: Data is safely stored in Turso&#39;s distributed database, surviving restarts/redeployments.</li><li><strong>Performance</strong>: AI analysis is significantly faster (cloud inference vs local CPU inference).</li><li><strong>Developer Experience</strong>: Simplified Dockerfile (or removal thereof) and standard <code>npm start</code> workflow.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li><strong>Latency</strong>: Potential network latency for DB/AI calls (mitigated by EU region selection).</li><li><strong>Dependency</strong>: Dependency on external services (Turso, Google) instead of a fully self-contained offline container.</li><li><strong>Cold Starts</strong>: Render&#39;s free tier has cold starts, but they are faster than the previous Docker timeout loops.</li></ul><h2 id="compliance" tabindex="-1">Compliance <a class="header-anchor" href="#compliance" aria-label="Permalink to &quot;Compliance&quot;">​</a></h2><p>This architecture adheres to the TFM requirement of &quot;Modern Web Development&quot; and &quot;Cloud Native&quot; patterns while respecting the &quot;Zero Cost&quot; constraint.</p>',19)])])}const p=t(n,[["render",a]]);export{g as __pageData,p as default};
